CREATE TABLE IF NOT EXISTS "v1_staging"."auth_users" (
  "instance_id" uuid,
  "id" uuid NOT NULL,
  "aud" character varying(255),
  "role" character varying(255),
  "email" character varying(255),
  "encrypted_password" character varying(255),
  "email_confirmed_at" timestamp with time zone,
  "invited_at" timestamp with time zone,
  "confirmation_token" character varying(255),
  "confirmation_sent_at" timestamp with time zone,
  "recovery_token" character varying(255),
  "recovery_sent_at" timestamp with time zone,
  "email_change_token_new" character varying(255),
  "email_change" character varying(255),
  "email_change_sent_at" timestamp with time zone,
  "last_sign_in_at" timestamp with time zone,
  "raw_app_meta_data" jsonb,
  "raw_user_meta_data" jsonb,
  "is_super_admin" boolean,
  "created_at" timestamp with time zone,
  "updated_at" timestamp with time zone,
  "phone" text,
  "phone_confirmed_at" timestamp with time zone,
  "phone_change" text,
  "phone_change_token" character varying(255),
  "phone_change_sent_at" timestamp with time zone,
  "confirmed_at" timestamp with time zone,
  "email_change_token_current" character varying(255),
  "email_change_confirm_status" smallint,
  "banned_until" timestamp with time zone,
  "reauthentication_token" character varying(255),
  "reauthentication_sent_at" timestamp with time zone,
  "is_sso_user" boolean NOT NULL,
  "deleted_at" timestamp with time zone,
  "is_anonymous" boolean NOT NULL,
  UNIQUE (phone),
  PRIMARY KEY (id)
);
CREATE UNIQUE INDEX IF NOT EXISTS "auth_users__confirmation_token_idx" ON "v1_staging"."auth_users" USING btree (confirmation_token) WHERE ((confirmation_token)::text !~ '^[0-9 ]*$'::text);
CREATE UNIQUE INDEX IF NOT EXISTS "auth_users__email_change_token_current_idx" ON "v1_staging"."auth_users" USING btree (email_change_token_current) WHERE ((email_change_token_current)::text !~ '^[0-9 ]*$'::text);
CREATE UNIQUE INDEX IF NOT EXISTS "auth_users__email_change_token_new_idx" ON "v1_staging"."auth_users" USING btree (email_change_token_new) WHERE ((email_change_token_new)::text !~ '^[0-9 ]*$'::text);
CREATE UNIQUE INDEX IF NOT EXISTS "auth_users__reauthentication_token_idx" ON "v1_staging"."auth_users" USING btree (reauthentication_token) WHERE ((reauthentication_token)::text !~ '^[0-9 ]*$'::text);
CREATE UNIQUE INDEX IF NOT EXISTS "auth_users__recovery_token_idx" ON "v1_staging"."auth_users" USING btree (recovery_token) WHERE ((recovery_token)::text !~ '^[0-9 ]*$'::text);
CREATE UNIQUE INDEX IF NOT EXISTS "auth_users__users_email_partial_key" ON "v1_staging"."auth_users" USING btree (email) WHERE (is_sso_user = false);

